        /* ============================================================
         * DRAGGABLE  (mouse + touch)
         * ============================================================ */
let dragging = false;

let dragOffsetX = 0;
let dragOffsetY = 0;

let lastTouchY = 0;
let lastTouchTime = 0;
let touchVelocityY = 0;

let restoreTop = null;

const OFFSCREEN_PERCENT = 0.8; // 80% can go off-screen
const FLING_VELOCITY = 0.7;    // Increase/decrease to control fling sensitivity


function isInteractive(target) {
    if (!target || !target.tagName) return false;

    const tag = target.tagName;
    return tag === 'TEXTAREA' || tag === 'BUTTON' || tag === 'INPUT';
}


// ============================================================
// GHOST ARROW
// ============================================================

function createGhostArrow(direction) {

    removeGhostArrow();

    const arrow = document.createElement('button');

    arrow.className = 'floating-div-ghost-arrow';

    arrow.innerText = direction === 'down' ? '↓' : '↑';

    arrow.setAttribute('aria-label',
        direction === 'down'
            ? 'Bring floating window down'
            : 'Bring floating window up'
    );
	
	arrow.style.top =
        direction === 'down'
            ? 'calc(100% - 14px)'  // bottom of div
            : '-28px';              // top of div

    arrow.style.bottom = 'auto';

    arrow.addEventListener('click', (e) => {
        e.preventDefault();
        e.stopPropagation();

        bringBackOnScreen();
    });

    floatDiv.appendChild(arrow);
}


function removeGhostArrow() {
    const arrow = floatDiv.querySelector('.floating-div-ghost-arrow');

    if (arrow) {
        arrow.remove();
    }
}


// ============================================================
// VERTICAL LIMITS
// ============================================================

function getVerticalLimits() {

    const height = floatDiv.offsetHeight;
    const viewportHeight = window.innerHeight;

    // Allow 80% of the floating div to leave the screen.
    // Therefore 20% must remain visible.

    const minTop = -(height * OFFSCREEN_PERCENT);

    const maxTop =
        viewportHeight -
        (height * (1 - OFFSCREEN_PERCENT));

    return {
        minTop,
        maxTop
    };
}


function clampVertical(top) {

    const limits = getVerticalLimits();

    return Math.max(
        limits.minTop,
        Math.min(top, limits.maxTop)
    );
}


// ============================================================
// DRAG START
// ============================================================

function startDrag(clientX, clientY) {

    dragging = true;

    removeGhostArrow();

    const rect = floatDiv.getBoundingClientRect();

    dragOffsetX = clientX - rect.left;
    dragOffsetY = clientY - rect.top;

    lastTouchY = clientY;
    lastTouchTime = performance.now();
    touchVelocityY = 0;

    // Stop any current CSS transition while dragging.
    floatDiv.style.transition = 'none';
}


// ============================================================
// DESKTOP DRAG
// ============================================================

function moveDrag(clientX, clientY) {

    if (!dragging) return;

    let newLeft = clientX - dragOffsetX;
    let newTop = clientY - dragOffsetY;

    const width = floatDiv.offsetWidth;
    const viewportWidth = window.innerWidth;

    // Desktop horizontal restriction.
    newLeft = Math.max(
        0,
        Math.min(newLeft, viewportWidth - width)
    );

    // Vertical restriction:
    // 20% of the div must remain visible.
    newTop = clampVertical(newTop);

    floatDiv.style.left = newLeft + 'px';
    floatDiv.style.top = newTop + 'px';
    floatDiv.style.right = 'auto';

    updateGhostArrow();
}


// ============================================================
// MOBILE DRAG
// ============================================================

function moveDragMob(clientX, clientY) {

    if (!dragging) return;

    const now = performance.now();

    // Calculate vertical finger velocity.
    const deltaY = clientY - lastTouchY;
    const deltaTime = now - lastTouchTime;

    if (deltaTime > 0) {
        touchVelocityY = deltaY / deltaTime;
    }

    lastTouchY = clientY;
    lastTouchTime = now;


    let newLeft = clientX - dragOffsetX;
    let newTop = clientY - dragOffsetY;

    const width = floatDiv.offsetWidth;

    // ========================================================
    // HORIZONTAL: CENTERED 90% VIEWPORT AREA
    // ========================================================

    const containerWidth = window.innerWidth * 0.9;

    const containerLeft =
        (window.innerWidth - containerWidth) / 2;

    const containerRight =
        containerLeft + containerWidth;

    newLeft = Math.max(
        containerLeft,
        Math.min(newLeft, containerRight - width)
    );


    // ========================================================
    // VERTICAL: 20% MUST REMAIN VISIBLE
    // ========================================================

    newTop = clampVertical(newTop);


    floatDiv.style.left = newLeft + 'px';
    floatDiv.style.top = newTop + 'px';
    floatDiv.style.right = 'auto';

    updateGhostArrow();
}


// ============================================================
// UPDATE GHOST ARROW
// ============================================================

function updateGhostArrow() {

    const rect = floatDiv.getBoundingClientRect();

    const viewportHeight = window.innerHeight;

    const limits = getVerticalLimits();

    // At the TOP: 80% is off-screen.
    if (rect.top <= limits.minTop + 1) {

        createGhostArrow('down');

        return;
    }

    // At the BOTTOM: 80% is off-screen.
    if (rect.top >= limits.maxTop - 1) {

        createGhostArrow('up');

        return;
    }

    removeGhostArrow();
}


// ============================================================
// FLING
// ============================================================

function flingVertical() {

    // Ignore tiny movements.
    if (Math.abs(touchVelocityY) < FLING_VELOCITY) {
        return false;
    }

    const rect = floatDiv.getBoundingClientRect();

    const limits = getVerticalLimits();

    let targetTop;

    if (touchVelocityY < 0) {

        // Finger moved upward quickly.
        // Throw floating div to the top.
        targetTop = limits.minTop;

        restoreTop = rect.top;

    } else {

        // Finger moved downward quickly.
        // Throw floating div to the bottom.
        targetTop = limits.maxTop;

        restoreTop = rect.top;
    }


    floatDiv.style.transition =
        'top 500ms cubic-bezier(0.22, 1, 0.36, 1)';

    floatDiv.style.top = targetTop + 'px';


    // Wait until animation has finished before showing arrow.
    setTimeout(() => {

        floatDiv.style.transition = 'none';

        updateGhostArrow();

    }, 510);

    return true;
}


// ============================================================
// BRING BACK FULLY ON SCREEN
// ============================================================

function bringBackOnScreen() {

    removeGhostArrow();

    const rect = floatDiv.getBoundingClientRect();

    let targetTop;

    // If it was pushed off the top, bring it to the top.
    if (rect.top < 0) {

        targetTop = 20;

    }

    // If it was pushed off the bottom, bring it to the bottom.
    else if (rect.bottom > window.innerHeight) {

        targetTop =
            window.innerHeight -
            floatDiv.offsetHeight -
            20;

    }

    // Otherwise simply restore the previous position.
    else {

        targetTop = restoreTop !== null
            ? restoreTop
            : rect.top;
    }


    // Make sure the restored position is completely visible.
    targetTop = Math.max(
        20,
        Math.min(
            targetTop,
            window.innerHeight - floatDiv.offsetHeight - 20
        )
    );


    floatDiv.style.transition =
        'top 450ms cubic-bezier(0.22, 1, 0.36, 1)';

    floatDiv.style.top = targetTop + 'px';


    setTimeout(() => {
        floatDiv.style.transition = 'none';
    }, 460);
}


// ============================================================
// END DRAG
// ============================================================

function endDrag() {

    if (!dragging) return;

    dragging = false;

    // On mobile, a fast swipe becomes a fling.
    if (Math.abs(touchVelocityY) >= FLING_VELOCITY) {

        if (flingVertical()) {
            return;
        }
    }

    floatDiv.style.transition = 'none';

    updateGhostArrow();
}


// ============================================================
// MOUSE
// ============================================================

floatDiv.addEventListener('mousedown', (e) => {

    if (isInteractive(e.target)) return;

    startDrag(e.clientX, e.clientY);
});


document.addEventListener('mousemove', (e) => {

    moveDrag(e.clientX, e.clientY);
});


document.addEventListener('mouseup', endDrag);


// ============================================================
// TOUCH
// ============================================================

floatDiv.addEventListener('touchstart', (e) => {

    if (isInteractive(e.target)) return;

    const t = e.touches[0];

    startDrag(t.clientX, t.clientY);

}, {
    passive: true
});


document.addEventListener('touchmove', (e) => {

    if (!dragging) return;

    e.preventDefault();

    const t = e.touches[0];

    moveDragMob(t.clientX, t.clientY);

}, {
    passive: false
});


document.addEventListener('touchend', endDrag);


// ============================================================
// RESIZE
// ============================================================

window.addEventListener('resize', () => {

    if (!floatDiv) return;

    const rect = floatDiv.getBoundingClientRect();

    const limits = getVerticalLimits();

    const newTop = Math.max(
        limits.minTop,
        Math.min(rect.top, limits.maxTop)
    );

    floatDiv.style.top = newTop + 'px';

    updateGhostArrow();
});

