async function fetchSession(token) {
    const maxAttempts = 3;

    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
        try {
            const res = await fetch(
                APPS_SCRIPT_URL + '?route=session&token=' + encodeURIComponent(token)
            );

            const data = await res.json();

            if (!res.ok || data.error) {
                throw new Error(data.error || 'Request failed');
            }

            return data;
        } catch (error) {
            if (attempt === maxAttempts) {
                throw error;
            }

            // Wait before retrying
            await new Promise(resolve => setTimeout(resolve, 2000));
        }
    }
}


        async function deleteSession(token) {
            if (!token) return;
            try {
                await fetch(APPS_SCRIPT_URL + '?route=delete', {
                    method: 'POST',
                    headers: { 'Content-Type': 'text/plain;charset=utf-8' },
                    body: JSON.stringify({ token: token })
                });
            } catch (err) {
                // best effort — the session simply stays until it is deleted manually
            }
        }

        /* ----------------------------------------------------------
         * Resolve one reference image into a File.
         * Drive links can't always be fetched straight from the page
         * (CORS), so file ids are pulled through the script's image
         * route, which returns the bytes as base64.
         * ---------------------------------------------------------- */
        async function resolveReferenceFile(ref) {
            try {
                if (typeof ref === 'string') {
                    if (ref.indexOf('data:') === 0) return dataUriToFile(ref);
                    const res = await fetch(ref);
                    const blob = await res.blob();
                    return new File([blob], refFileName(blob.type), { type: blob.type });
                }
                if (ref && ref.file_id) {
                    const res = await fetch(APPS_SCRIPT_URL + '?route=image&id=' + encodeURIComponent(ref.file_id));
                    const data = await res.json();
                    if (data && data.data) return base64ToFile(data.data, data.mime || ref.mime, ref.name || data.name);
                }
                if (ref && ref.url) {
                    const res = await fetch(ref.url);
                    const blob = await res.blob();
                    return new File([blob], refFileName(blob.type), { type: blob.type });
                }
            } catch (err) {
                // skip unreadable reference images
            }
            return null;
        }

async function resolveReferenceFiles(refs) {
    const files = [];

    for (const ref of refs) {
        let file;

        for (let attempt = 1; attempt <= 6; attempt++) {
            file = await resolveReferenceFile(ref);

            if (file) break;
        }

        if (file) files.push(file);
    }

    return files;
}

